await setAccountFlags(client, wallet, setFlag);

client.disconnect();
```

## 5. Creating issueCurrency.js
Define a generic method to issue tokens.

```javascript
// utils/payment.js

// Function to issue tokens
export async function issueCurrency(
  client,
  issuerWallet,
  recipientAddress,
  currency,
  amount
) {
